styles:
:root{
    /* ---- Paleta tomada de la web (verde) ---- */
    --ink:#234E48;         /* verde profundo · titulos y acentos */
    --ink-soft:#5C7C75;    /* texto de lectura */
    --green:#4F9E8E;       /* verde principal */
    --green-d:#3B8375;     /* verde oscuro */
    --green-deep:#1E6A64;  /* boton CTA */
    --green-pale:#A9D6C8;  /* acentos claros sobre fondo oscuro */
    --cream:#E9F1E9;       /* fondo */
    --cream-2:#F3F8F2;     /* fondo claro */
    --amber:#B79A63;
    --black:#16332F;
    --white:#ffffff;
    --display:var(--font-display),Georgia,serif;
    --sans:var(--font-jost),system-ui,sans-serif;
    --bold:var(--font-montserrat),system-ui,sans-serif;
    --script:var(--font-caveat),cursive;
  }

  *{box-sizing:border-box;margin:0;padding:0}

  body{
    font-family:var(--sans);
    color:var(--ink-soft);
    line-height:1.6;
    background-color:var(--cream);
    background-image:
      url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22340%22%20height%3D%22340%22%20viewBox%3D%220%200%20340%20340%22%3E%20%3Cg%20fill%3D%22none%22%20stroke%3D%22%23234E48%22%20stroke-width%3D%221.3%22%20stroke-linecap%3D%22round%22%20stroke-opacity%3D%220.10%22%3E%20%3C%21--%20florcita%205%20petalos%20--%3E%20%3Cg%20transform%3D%22translate%2870%2C72%29%22%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%22-11%22%20rx%3D%224.6%22%20ry%3D%2210%22%2F%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%22-11%22%20rx%3D%224.6%22%20ry%3D%2210%22%20transform%3D%22rotate%2872%29%22%2F%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%22-11%22%20rx%3D%224.6%22%20ry%3D%2210%22%20transform%3D%22rotate%28144%29%22%2F%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%22-11%22%20rx%3D%224.6%22%20ry%3D%2210%22%20transform%3D%22rotate%28216%29%22%2F%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%22-11%22%20rx%3D%224.6%22%20ry%3D%2210%22%20transform%3D%22rotate%28288%29%22%2F%3E%20%3Ccircle%20r%3D%222.4%22%2F%3E%20%3C%2Fg%3E%20%3C%21--%20ramita%20con%20hojitas%20--%3E%20%3Cg%3E%20%3Cpath%20d%3D%22M250%2044%20q%2016%2026%207%2058%22%2F%3E%20%3Cellipse%20cx%3D%22262%22%20cy%3D%2262%22%20rx%3D%223.4%22%20ry%3D%228%22%20transform%3D%22rotate%2842%20262%2062%29%22%2F%3E%20%3Cellipse%20cx%3D%22250%22%20cy%3D%2278%22%20rx%3D%223.4%22%20ry%3D%228%22%20transform%3D%22rotate%28-34%20250%2078%29%22%2F%3E%20%3Cellipse%20cx%3D%22262%22%20cy%3D%2292%22%20rx%3D%223.4%22%20ry%3D%228%22%20transform%3D%22rotate%2846%20262%2092%29%22%2F%3E%20%3C%2Fg%3E%20%3C%21--%20florcita%205%20petalos%20--%3E%20%3Cg%20transform%3D%22translate%28280%2C250%29%20scale%28.92%29%22%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%22-11%22%20rx%3D%224.6%22%20ry%3D%2210%22%2F%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%22-11%22%20rx%3D%224.6%22%20ry%3D%2210%22%20transform%3D%22rotate%2872%29%22%2F%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%22-11%22%20rx%3D%224.6%22%20ry%3D%2210%22%20transform%3D%22rotate%28144%29%22%2F%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%22-11%22%20rx%3D%224.6%22%20ry%3D%2210%22%20transform%3D%22rotate%28216%29%22%2F%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%22-11%22%20rx%3D%224.6%22%20ry%3D%2210%22%20transform%3D%22rotate%28288%29%22%2F%3E%20%3Ccircle%20r%3D%222.4%22%2F%3E%20%3C%2Fg%3E%20%3C%21--%20ramita%20con%20hojitas%20--%3E%20%3Cg%3E%20%3Cpath%20d%3D%22M96%20250%20q%20-18%2024%20-6%2056%22%2F%3E%20%3Cellipse%20cx%3D%2284%22%20cy%3D%22268%22%20rx%3D%223.4%22%20ry%3D%228%22%20transform%3D%22rotate%28-42%2084%20268%29%22%2F%3E%20%3Cellipse%20cx%3D%2296%22%20cy%3D%22284%22%20rx%3D%223.4%22%20ry%3D%228%22%20transform%3D%22rotate%2834%2096%20284%29%22%2F%3E%20%3Cellipse%20cx%3D%2284%22%20cy%3D%22298%22%20rx%3D%223.4%22%20ry%3D%228%22%20transform%3D%22rotate%28-46%2084%20298%29%22%2F%3E%20%3C%2Fg%3E%20%3C%21--%20pimpollo%20%2F%20capullo%20--%3E%20%3Cg%20transform%3D%22translate%28175%2C168%29%22%3E%20%3Cpath%20d%3D%22M0%206%20q%20-7%20-8%200%20-18%20q%207%2010%200%2018%22%2F%3E%20%3Cpath%20d%3D%22M0%20-12%20v%2020%22%2F%3E%20%3Cpath%20d%3D%22M0%204%20l%20-6%204%20M0%204%20l%206%204%22%2F%3E%20%3C%2Fg%3E%20%3C%21--%20hojita%20suelta%20--%3E%20%3Cg%20transform%3D%22translate%2840%2C200%29%20rotate%2820%29%22%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%220%22%20rx%3D%224%22%20ry%3D%229%22%2F%3E%20%3Cpath%20d%3D%22M0%20-9%20v%2018%22%2F%3E%20%3C%2Fg%3E%20%3C%21--%20hojita%20suelta%20--%3E%20%3Cg%20transform%3D%22translate%28215%2C118%29%20rotate%28-25%29%22%3E%20%3Cellipse%20cx%3D%220%22%20cy%3D%220%22%20rx%3D%224%22%20ry%3D%229%22%2F%3E%20%3Cpath%20d%3D%22M0%20-9%20v%2018%22%2F%3E%20%3C%2Fg%3E%20%3C%2Fg%3E%20%3C%2Fsvg%3E"),
      radial-gradient(135% 95% at 50% -12%, var(--cream-2) 0%, var(--cream) 55%, #DCE9E1 100%);
    background-repeat:repeat, no-repeat;
    background-size:340px 340px, cover;
    background-attachment:fixed, fixed;
    -webkit-font-smoothing:antialiased;
    min-height:100vh;
    overflow-x:hidden;
  }

  /* fondo de florcitas en body (igual a la web) */

  .wrap{
    position:relative;z-index:1;
    max-width:740px;
    margin:0 auto;
    padding:64px 24px 80px;
  }

  /* ---------- PORTADA (Opción 1 · tapa vino) ---------- */
  .cover{
    position:relative;
    margin-top:-64px;
    margin-left:calc(50% - 50vw);
    margin-right:calc(50% - 50vw);
    margin-bottom:clamp(18px,3.5vh,36px);
    min-height:82vh;
    display:flex;flex-direction:column;align-items:center;justify-content:center;
    text-align:center;
    padding:clamp(78px,12vh,140px) 26px clamp(72px,11vh,120px);
    overflow:hidden;
    background:linear-gradient(165deg,#2F7A6E 0%,#245F58 58%,#1A4340 100%);
  }
  .cover-inner{
    position:relative;z-index:1;
    max-width:620px;margin:0 auto;
    background:none;border:0;box-shadow:none;backdrop-filter:none;padding:0;
  }
  .cover-bow{display:block;width:clamp(54px,9vw,68px);color:var(--green-pale);margin:0 auto clamp(20px,3.4vw,30px)}
  .cover-bow svg{width:100%;height:auto;display:block}
  .cover-eyebrow{
    font-family:var(--sans);font-weight:500;text-transform:uppercase;
    letter-spacing:.3em;font-size:clamp(10.5px,2vw,12px);color:var(--green-pale);
    margin-bottom:clamp(18px,3vw,26px);
  }
  .cover-eyebrow::before,.cover-eyebrow::after{content:'·';margin:0 .7em;color:var(--green)}
  .cover-title{
    font-family:var(--display);font-weight:500;
    font-size:clamp(40px,8.4vw,66px);line-height:1.04;
    letter-spacing:-.015em;color:#fff;
  }
  .cover-title em{font-style:italic;font-weight:500;display:block;margin-top:4px;color:var(--green-pale)}
  .cover-flourish{
    width:clamp(120px,26vw,178px);height:auto;color:var(--green-pale);
    margin:clamp(18px,3vw,26px) auto 0;display:block;opacity:.85;
  }
  .cover-tag{
    max-width:440px;margin:clamp(20px,3.4vw,28px) auto 0;
    font-size:clamp(15px,2.6vw,18px);font-weight:300;line-height:1.65;color:rgba(255,255,255,.82);
  }
  .cover-author{
    margin-top:clamp(18px,3.2vw,26px);
    font-family:var(--script);font-weight:600;font-size:clamp(28px,4vw,34px);color:var(--green-pale);line-height:1;
  }
  .cover-author small{
    display:block;font-family:var(--sans);font-weight:400;text-transform:uppercase;
    letter-spacing:.24em;font-size:9px;color:rgba(255,255,255,.6);margin-bottom:4px;
  }

  /* ---------- ANTESALA (título + línea fina) ---------- */
  .opener{
    text-align:center;
    max-width:560px;
    margin:0 auto clamp(30px,5vw,46px);
  }
  .opener .k{
    font-family:var(--sans);font-weight:600;text-transform:uppercase;
    letter-spacing:.28em;font-size:11px;color:var(--ink);
  }
  .opener h2{
    font-family:var(--display);font-weight:500;font-style:italic;
    font-size:clamp(22px,4.2vw,31px);line-height:1.2;
    color:var(--ink);margin-top:8px;letter-spacing:-.01em;
  }
  .hairline{
    width:100%;max-width:280px;height:1px;margin:20px auto 0;
    background:linear-gradient(90deg,transparent,rgba(35,78,72,.34),transparent);
  }

  /* ---------- HERO ---------- */
  .hero{text-align:center;margin-bottom:54px}

  .eyebrow{
    font-family:var(--sans);
    font-weight:500;
    text-transform:uppercase;
    letter-spacing:.34em;
    font-size:12px;
    color:var(--ink);
    margin-bottom:22px;
  }
  .eyebrow::before,.eyebrow::after{content:'·';margin:0 .7em;color:var(--green)}

  .hero h1{
    font-family:var(--display);
    font-weight:500;
    font-size:clamp(30px,6.4vw,46px);
    line-height:1.12;
    color:var(--ink);
    letter-spacing:-.01em;
  }
  .hero h1 em{
    font-style:italic;
    font-weight:500;
    display:block;
    margin-top:6px;
  }

  .hero .lead{
    max-width:660px;
    margin:24px auto 0;
    font-size:clamp(16.5px,2.8vw,19.5px);
    font-weight:400;
    color:var(--ink);
    line-height:1.65;
  }

  .ribbon{
    width:60px;height:2px;border:0;border-radius:2px;
    background:linear-gradient(90deg,transparent,var(--green),transparent);
    margin:34px auto 0;
  }

  /* ---------- INTRO / CARTA (abierta, sin caja) ---------- */
  .intro{
    max-width:600px;
    margin:0 auto 34px;
    padding:0 6px;
    text-align:center;
  }
  .intro p{
    font-size:clamp(17px,2.7vw,19.5px);
    font-weight:300;
    line-height:1.62;
    color:var(--ink-soft);
    margin-bottom:6px;
  }
  .intro p:last-child{margin-bottom:0}
  .intro strong{font-weight:500;color:var(--ink)}

  /* ---------- DIVISOR ---------- */
  .divider{
    display:flex;align-items:center;justify-content:center;gap:12px;
    max-width:300px;margin:6px auto 44px;
  }
  .divider::before,.divider::after{
    content:'';height:1px;flex:1;
  }
  .divider::before{background:linear-gradient(90deg,transparent,rgba(35,78,72,.34))}
  .divider::after{background:linear-gradient(90deg,rgba(35,78,72,.34),transparent)}
  .divider span{
    width:6px;height:6px;border-radius:50%;
    background:var(--green);flex:0 0 auto;
    box-shadow:0 0 0 4px rgba(79,158,142,.20);
  }

  /* ---------- PASOS (estilo módulos) ---------- */
  .pasos-head{text-align:center;margin-bottom:30px}
  .pasos-head .k{
    font-family:var(--sans);font-weight:500;text-transform:uppercase;
    letter-spacing:.28em;font-size:11px;color:var(--ink);
  }
  .pasos-head h2{
    font-family:var(--display);font-weight:500;
    font-size:clamp(22px,4vw,30px);color:var(--black);
    margin-top:8px;line-height:1.2;
  }

  .panel{
    background:rgba(255,255,255,.6);
    border:1px solid rgba(255,255,255,.75);
    border-radius:26px;
    padding:18px clamp(14px,3vw,26px);
    box-shadow:0 24px 60px -34px rgba(35,78,72,.55);
  }

  .paso{
    display:flex;
    gap:20px;
    padding:26px 8px;
    border-bottom:1px solid rgba(35,78,72,.14);
  }
  .paso:last-child{border-bottom:0}

  .num{
    flex:0 0 auto;
    font-family:var(--display);
    font-weight:500;
    font-size:clamp(26px,5vw,34px);
    line-height:1;
    color:var(--green);
    width:46px;
    text-align:center;
    padding-top:4px;
  }

  .paso-body{flex:1 1 auto;min-width:0}

  .paso-body h3{
    font-family:var(--script);
    font-weight:700;
    font-size:clamp(26px,4.6vw,33px);
    line-height:1.05;
    color:var(--ink);
    margin-bottom:8px;
  }
  .paso-body p{
    font-size:clamp(14.5px,2.2vw,16px);
    font-weight:300;
    color:var(--ink-soft);
  }

  .micro{
    margin-top:14px;
    background:rgba(79,158,142,.13);
    border-left:3px solid var(--green);
    border-radius:0 12px 12px 0;
    padding:11px 16px;
    font-size:14px;
  }
  .micro b{
    display:block;
    font-family:var(--sans);
    font-weight:600;
    text-transform:uppercase;
    letter-spacing:.14em;
    font-size:10.5px;
    color:var(--ink);
    margin-bottom:3px;
  }
  .micro span{font-weight:300;color:var(--black)}

  /* ---------- ACTIVACIÓN / COMPROMISO ---------- */
  .activar{
    margin-top:48px;
    background:rgba(255,255,255,.6);
    border:1.5px dashed var(--green);
    border-radius:26px;
    padding:34px clamp(20px,4vw,38px);
    text-align:center;
  }
  .activar .k{
    font-family:var(--sans);font-weight:600;text-transform:uppercase;
    letter-spacing:.24em;font-size:11px;color:var(--ink);
  }
  .activar h2{
    font-family:var(--display);font-weight:500;
    font-size:clamp(23px,4.4vw,32px);color:var(--black);
    margin:8px 0 6px;line-height:1.15;
  }
  .activar .sub{
    font-size:clamp(14.5px,2.2vw,16px);font-weight:300;color:var(--ink-soft);
    max-width:520px;margin:0 auto 24px;
  }
  .activar .sub b{font-weight:600;color:var(--ink)}
  .fill{
    text-align:left;max-width:480px;margin:0 auto;
  }
  .fill .row{margin-bottom:20px}
  .fill label{
    display:block;font-family:var(--sans);font-weight:600;
    text-transform:uppercase;letter-spacing:.12em;font-size:11px;
    color:var(--ink);margin-bottom:9px;
  }
  .fill .line{
    height:30px;border-bottom:2px solid var(--green);
    border-radius:0 0 3px 3px;
  }
  .kick{
    margin-top:26px;
    font-family:var(--display);font-style:italic;font-weight:500;
    font-size:clamp(17px,2.8vw,20px);line-height:1.4;color:var(--ink);
  }
  .kick b{font-style:normal;font-weight:600;color:var(--black)}


  .cierre{
    text-align:center;
    margin-top:50px;
    background:linear-gradient(160deg,#2F7A6E 0%,#1E5A52 100%);
    color:#fff;
    border-radius:26px;
    padding:42px 30px;
    box-shadow:0 26px 60px -30px rgba(20,58,53,.6);
  }
  .cierre .frase{
    font-family:var(--display);
    font-style:italic;
    font-weight:400;
    font-size:clamp(20px,3.6vw,26px);
    line-height:1.35;
    color:#fff;
  }
  .cierre .frase b{font-weight:600;font-style:normal}
  .cierre p{
    margin-top:18px;
    font-size:15px;
    font-weight:300;
    color:rgba(255,255,255,.86);
    max-width:480px;
    margin-left:auto;margin-right:auto;
  }
  .firma{
    margin-top:26px;
    font-family:var(--script);
    font-weight:600;
    font-size:30px;
    color:var(--green-pale);
  }
  .firma small{
    display:block;
    font-family:var(--sans);
    font-weight:400;
    text-transform:uppercase;
    letter-spacing:.26em;
    font-size:10px;
    color:rgba(255,255,255,.6);
    margin:0 0 6px;
  }

  /* ---------- CTA SESIÓN ---------- */
  .cta-sesion{
    text-align:center;
    margin-top:44px;
    padding:8px 16px;
  }
  .cta-line{
    font-family:var(--display);
    font-weight:500;
    font-style:italic;
    font-size:clamp(20px,3.6vw,26px);
    line-height:1.3;
    color:var(--ink);
  }
  .cta-sub{
    max-width:480px;
    margin:14px auto 26px;
    font-size:clamp(14.5px,2.2vw,16px);
    font-weight:300;
    color:var(--ink-soft);
  }
  .cta-btn{
    display:inline-block;
    background:var(--green-deep);
    color:#fff;
    text-decoration:none;
    font-family:var(--sans);
    font-weight:600;
    text-transform:uppercase;
    letter-spacing:.16em;
    font-size:14px;
    padding:17px 38px;
    border-radius:999px;
    box-shadow:0 14px 30px -12px rgba(35,78,72,.6);
    transition:transform .18s ease, box-shadow .18s ease, background .18s ease;
  }
  .cta-btn:hover{
    background:#175752;
    transform:translateY(-2px);
    box-shadow:0 18px 36px -12px rgba(35,78,72,.7);
  }
  .cta-btn:focus-visible{outline:3px solid var(--green-d);outline-offset:3px}

  .cta-wpp{
    margin-top:16px;
    font-family:var(--sans);
    font-weight:600;
    font-size:14px;
    letter-spacing:.04em;
    color:var(--ink);
  }

  .pie{
    text-align:center;
    margin-top:12px;
    font-size:17px;
    font-weight:600;
    color:var(--ink);
    letter-spacing:.02em;
  }

  @media (max-width:480px){
    .wrap{padding:48px 18px 64px}
    .cover{margin-top:-48px;padding:clamp(60px,11vh,104px) 0 28px}
    .paso{gap:14px;padding:22px 2px}
    .num{width:36px}
    .intro,.panel{border-radius:20px}
  }


  @media print{
    .cover{min-height:100vh;page-break-after:always;break-after:page}
  }
@media(max-width:480px){.cover{margin-left:-18px;margin-right:-18px;padding-inline:18px}}
